<?php
session_start();require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/goliath-scout-intelligence.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ($http>=200&&$http<300&&is_array($d))?$d:[];}
$leads=sbq('goliath_scout_leads?select=*&order=created_at.desc&limit=200');
$new=count(array_filter($leads,fn($l)=>($l['status']??'')==='new'));
$phones=count(array_filter($leads,fn($l)=>!empty($l['owner_phone'])));
$emails=count(array_filter($leads,fn($l)=>!empty($l['owner_email'])));
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scout Contact Intelligence</title><link rel="stylesheet" href="/dashboard/assets/goliath-v33.css?v=459"><link rel="stylesheet" href="/dashboard/assets/goliath-v45-final.css?v=459"><style>.metricRow{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:14px 0}.miniK{background:#111827;border:1px solid rgba(255,255,255,.12);border-radius:18px;padding:16px}.miniK b{font-size:28px;color:#f8d77a}.gTable td,.gTable th{vertical-align:top}.pill{display:inline-block;padding:3px 8px;border-radius:20px;background:#18233a;color:#cfe1ff;font-size:12px}.warn{color:#ffd27a;font-size:12px}@media(max-width:900px){.metricRow{grid-template-columns:1fr 1fr}.gTable{font-size:12px}}</style></head><body><div class="shell"><?php require __DIR__.'/includes/goliath-sidebar-v33.php'; ?><main class="main"><section class="top"><div><h1>🕵️ Scout Contact Intelligence</h1><p>Expireds, foreclosures, public owner signals, verified phone/email candidates, and appointment opportunities.</p></div><div class="brandbar"><a class="btn dark" href="/dashboard/goliath-mission-control.php">Mission Control</a><button class="btn" onclick="seedScout()">Run Scout Now</button><a class="btn" href="/dashboard/goliath-appointment-queue.php">Jessica Queue</a></div></section><div class="metricRow"><div class="miniK"><b><?=number_format(count($leads))?></b><br>Total leads</div><div class="miniK"><b><?=number_format($new)?></b><br>New</div><div class="miniK"><b><?=number_format($phones)?></b><br>Phones found</div><div class="miniK"><b><?=number_format($emails)?></b><br>Emails found</div></div><section class="panel"><h2>Scout Findings <span>click a source when available</span></h2><div class="inner"><table class="gTable"><thead><tr><th>Owner / Property</th><th>Contact</th><th>Source / Status</th><th>Action</th></tr></thead><tbody><?php if(!$leads):?><tr><td colspan="4">No Scout leads yet. Run Scout Now, import your expired list, or let the local runner add verified findings.</td></tr><?php endif;?><?php foreach($leads as $l):?><tr><td><strong><?=h($l['owner_name']?:'Owner unknown')?></strong><br><?=h($l['property_address']??'')?><br><?=h($l['town']??'')?> <?=h($l['state']??'CT')?></td><td><?=!empty($l['owner_phone'])?'☎ '.h($l['owner_phone']).'<br>':''?><?=!empty($l['owner_email'])?'✉ '.h($l['owner_email']).'<br>':''?><span class="pill">Confidence <?=h($l['confidence']??0)?>%</span><br><span class="warn">DNC/consent: <?=h($l['dnc_status']??'unknown')?></span></td><td><strong><?=h($l['lead_type']??'')?></strong><br><?=h($l['source']??'')?><?php if(!empty($l['source_url'])):?><br><a href="<?=h($l['source_url'])?>" target="_blank">Open source</a><?php endif;?><br><small><?=h($l['notes']??'')?></small></td><td><button class="btn" onclick='queueEmail(<?=json_encode($l,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>Create Jessica Email</button></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script>async function seedScout(){const r=await fetch('/lead-engine/goliath-scout-engine.php?key=timetomakethedonuts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'seed_tasks'})});const j=await r.json();alert(j.message||JSON.stringify(j));location.reload()}async function queueEmail(l){const r=await fetch('/lead-engine/goliath-scout-engine.php?key=timetomakethedonuts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'add_lead',source:l.source||'manual_review',property_address:l.property_address,town:l.town,owner_name:l.owner_name,owner_email:l.owner_email,owner_phone:l.owner_phone,lead_type:l.lead_type,confidence:l.confidence,notes:'Manual Jessica email requested from Scout page'})});const j=await r.json();alert(j.success?'Jessica email queued for review':'Could not queue email');}</script></body></html>
